type UserId = string | number;

function formatId(id: UserId): string {
  if (typeof id === "string") {
    return id.trim().toUpperCase();
  }
  return `#${id.toFixed(0)}`;
}

formatId("abc-42");  // "ABC-42"
formatId(42);          // "#42"

type PaymentStatus = "pending" | "paid" | "failed";

function badge(status: PaymentStatus): string {
  switch (status) {
    case "pending": return "⏳";
    case "paid": return "✓";
    case "failed": return "✗";
    default: {
      const _exhaustive: never = status;
      return _exhaustive;
    }
  }
}

type Profile = { name: string; avatarUrl: string | null };

function displayAvatar(profile: Profile): string {
  if (profile.avatarUrl === null) {
    return "default.png";
  }
  // avatarUrl narrowed to string
  return profile.avatarUrl;
}

